<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { consultarCuadroGeneral, obtenerMesesCuadroGeneral, obtenerOpcionesCuadroGeneral } from '../services/cuadroGeneralCuentas'
import type { CuentaCuadroOption, CuadroGeneralData, FiltrosCuadroGeneral, PeriodoCuadro } from '../interfaces/cuadroGeneralCuentas.interface'
const filtros=reactive<FiltrosCuadroGeneral>({cuenta_desde:'',cuenta_hasta:'',anio:null,mes_inicio:null,mes_fin:null,tipo_saldo:'mensual'})
const anios=ref<number[]>([]),cuentas=ref<CuentaCuadroOption[]>([]),meses=ref<PeriodoCuadro[]>([]),data=ref<CuadroGeneralData|null>(null),loading=ref(false),consultado=ref(false),error=ref('')
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la consulta.'
const money=(v:number|null|undefined)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))
async function load(){loading.value=true;try{const r=await obtenerOpcionesCuadroGeneral();anios.value=r.anios;cuentas.value=r.cuentas_lista;meses.value=r.meses??[];data.value=r.data}catch(v){error.value=message(v)}finally{loading.value=false}}
async function changeYear(){filtros.mes_inicio=null;filtros.mes_fin=null;meses.value=[];if(!filtros.anio)return;try{meses.value=await obtenerMesesCuadroGeneral(filtros.anio)}catch(v){error.value=message(v)}}
async function search(){error.value='';if(!filtros.cuenta_desde||!filtros.cuenta_hasta||!filtros.anio||!filtros.mes_inicio||!filtros.mes_fin)return void(error.value='Complete todos los filtros obligatorios.');if(filtros.cuenta_desde>filtros.cuenta_hasta)return void(error.value='La cuenta inicial no puede ser mayor que la cuenta final.');if(filtros.mes_inicio>filtros.mes_fin)return void(error.value='El mes inicial no puede ser mayor que el mes final.');loading.value=true;consultado.value=true;try{const r=await consultarCuadroGeneral(filtros);data.value=r.data;if(r.meses?.length)meses.value=r.meses}catch(v){error.value=message(v);data.value=null}finally{loading.value=false}}
function clear(){Object.assign(filtros,{cuenta_desde:'',cuenta_hasta:'',anio:null,mes_inicio:null,mes_fin:null,tipo_saldo:'mensual'});meses.value=[];data.value=null;consultado.value=false;error.value=''}
const indent=(nivel:number)=>`${Math.min(Math.max(nivel-1,0),8)*14}px`
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/proceso-contable">Proceso contable</RouterLink> / Cuadro general de cuentas</nav><header class="hero"><div class="mark">CG</div><div><small>MIA · CONTABILIDAD · PROCESO</small><h1>Cuadro general de cuentas</h1><p>Consulta el plan de cuentas consolidado y sus saldos por periodo contable.</p></div></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="search"><label>Cuenta desde *<select v-model="filtros.cuenta_desde"><option value="">Seleccione</option><option v-for="o in cuentas" :key="o.cta_contable" :value="o.cta_contable">{{o.cta_contable}} - {{o.descripcion}}</option></select></label><label>Cuenta hasta *<select v-model="filtros.cuenta_hasta"><option value="">Seleccione</option><option v-for="o in cuentas" :key="o.cta_contable" :value="o.cta_contable">{{o.cta_contable}} - {{o.descripcion}}</option></select></label><label>Año *<select v-model="filtros.anio" @change="changeYear"><option :value="null">Seleccione</option><option v-for="o in anios" :key="o" :value="o">{{o}}</option></select></label><label>Mes inicial *<select v-model="filtros.mes_inicio"><option :value="null">Seleccione</option><option v-for="o in meses" :key="o.id" :value="o.mes">{{o.mes_label}}</option></select></label><label>Mes final *<select v-model="filtros.mes_fin"><option :value="null">Seleccione</option><option v-for="o in meses" :key="o.id" :value="o.mes">{{o.mes_label}}</option></select></label><label>Modalidad<select v-model="filtros.tipo_saldo"><option value="mensual">Mensual</option><option value="acumulado">Acumulado</option></select></label><footer><button type="button" class="soft" @click="clear">Limpiar</button><button :disabled="loading">{{loading?'Consultando…':'Consultar'}}</button></footer></form><div v-if="loading" class="empty">Consolidando saldos contables…</div><div v-else-if="consultado&&!data?.cuentas.length" class="empty">No se encontraron cuentas para los filtros seleccionados.</div><div v-else-if="!data" class="empty">Seleccione el rango de cuentas y periodos para generar el cuadro.</div><main v-else><header class="summary"><div><b>Rango de cuentas</b><span>{{data.cuenta_desde}} — {{data.cuenta_hasta}}</span></div><div><b>Periodo</b><span>{{data.anio}} · meses {{data.mes_inicio}} a {{data.mes_fin}}</span></div><div><b>Modalidad</b><span>{{data.tipo_saldo==='acumulado'?'Acumulado':'Mensual'}}</span></div><div><b>Cuentas</b><span>{{data.cuentas.length}}</span></div></header><div class="scroll"><table><thead><tr><th>Cuenta contable</th><th>Descripción</th><th v-for="p in data.periodos" :key="p.id" class="num">{{p.mes_label}}</th><th class="num">Saldo acumulado</th></tr></thead><tbody><tr v-for="(fila,i) in data.cuentas" :key="`${fila.cta_contable}-${fila.grupo}-${i}`" :class="{total:fila.es_total,parent:fila.es_padre}"><td><b>{{fila.cta_contable}}</b></td><td><span :style="{paddingLeft:indent(fila.nivel)}">{{fila.descripcion}}</span></td><td v-for="p in data.periodos" :key="p.id" class="num">{{fila.es_padre?'—':money(fila.saldos_mensuales[p.id])}}</td><td class="num"><b v-if="!fila.es_padre">{{money(fila.saldo_acumulado)}}</b><span v-else>—</span></td></tr></tbody></table></div></main></div></template>
<style scoped>
.page{--a:#32936f;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.flash{padding:9px;color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:15px;display:grid;grid-template-columns:repeat(6,1fr);gap:8px;background:#fff}.filters label{display:grid;gap:5px;font-size:.49rem}.filters select{min-width:0;padding:9px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.5rem}.filters footer{grid-column:1/-1;display:flex;justify-content:flex-end;gap:6px}.filters button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.soft{color:#64727a!important;background:#edf1f3!important}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff}.summary{margin-top:14px;padding:12px;display:grid;grid-template-columns:repeat(4,1fr);gap:8px;background:#fff}.summary div{display:grid;gap:3px;font-size:.52rem}.summary b{color:#728087}.summary span{font-size:.6rem}.scroll{overflow:auto;background:#fff}table{width:100%;min-width:900px;border-collapse:collapse;font-size:.5rem}th,td{padding:8px;border:1px solid #e1e7ea;text-align:left}thead{background:#e6f1ed}tbody tr:hover{background:#f5faf8}.num{text-align:right;font-family:monospace}.parent{color:#66747b;background:#f4f6f7}.total{font-weight:700;background:#dcece6!important}@media(max-width:900px){.filters{grid-template-columns:repeat(3,1fr)}.summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:580px){.filters,.summary{grid-template-columns:1fr}}
</style>
